def verify_native(read, base):
    """Pin the name property, signed converter, stored code and lookup route."""
    end = max(rva + len(expected) for rva, expected in NATIVE_SPANS)
    if type(base) is not int or base < 4096 or base % 8 or base + end >= 1 << 64:
        raise ValueError('Invalid training session native base')
    for rva, expected in NATIVE_SPANS:
        actual = read(base + rva, len(expected))
        if actual != expected:
            raise ValueError(f'Training session native route changed at RVA {rva:#x}')


def _stamp(value):
    return value.st_dev, value.st_ino, value.st_size, value.st_mtime_ns, change_time_ns(value)


def _bounded_file(path, limit):
    path_before = path.stat()
    if not stat.S_ISREG(path_before.st_mode) or not 0 < path_before.st_size <= limit:
        return None
    with path.open('rb') as handle:
        before = os.fstat(handle.fileno())
        if (_stamp(before) != _stamp(path_before) or not stat.S_ISREG(before.st_mode)
                or not 0 < before.st_size <= limit):
            return None
        raw = handle.read(limit + 1)
        if (len(raw) != before.st_size or _stamp(before) != _stamp(os.fstat(handle.fileno()))
                or _stamp(before) != _stamp(path.stat())):
            return None
        return raw


def resource_matches(executable):
    """Check only the standard resource inside the attached FM27 application.

    The bridge owns kernel process identity checks. This function validates the
    executable's bundle metadata and reads a bounded regular resource file; a
    missing, changed, escaped or unsupported bundle returns False.
    """
    try:
        executable = Path(executable)
        if not executable.is_absolute():
            return False
        executable = executable.resolve(strict=True)
        if (executable.name not in ('fm', 'Football Manager 27')
                or executable.parent.name != 'MacOS'
                or executable.parent.parent.name != 'Contents'
                or executable.parent.parent.parent.suffix != '.app'
                or not stat.S_ISREG(executable.stat().st_mode)):
            return False
        contents = executable.parent.parent
        metadata_path = (contents / 'Info.plist').resolve(strict=True)
        resource_path = (contents / RESOURCE_RELATIVE_PATH).resolve(strict=True)
        if not metadata_path.is_relative_to(contents) or not resource_path.is_relative_to(contents):
            return False
        raw_metadata = _bounded_file(metadata_path, 65536)
        if raw_metadata is None:
            return False
        metadata = plistlib.loads(raw_metadata)
        if (not isinstance(metadata, dict)
                or metadata.get('CFBundleIdentifier') != 'com.SportsInteractive.FootballManager27'
                or metadata.get('CFBundleExecutable') != executable.name
                or metadata.get('CFBundleShortVersionString') != players.VERSION):
            return False
        resource = _bounded_file(resource_path, RESOURCE_SIZE)
        return (resource is not None and len(resource) == RESOURCE_SIZE
                and hashlib.sha256(resource).hexdigest() == RESOURCE_SHA256)
    except (OSError, ValueError, TypeError, plistlib.InvalidFileException, ExpatError):
        return False


def label(slot_index, code, resource_verified):
    """Preserve signed code and distinguish unknown names from resource absence."""
    if type(slot_index) is not int or not 0 <= slot_index <= 2:
        raise ValueError('Training session slot index must be an integer from 0 to 2')
    if type(code) is not int or not -32768 <= code <= 32767:
        raise ValueError('Training session code must be a signed 16-bit integer')
    if type(resource_verified) is not bool:
        raise ValueError('Training definition resource verification must be a boolean')
    name = SESSION_NAMES.get(code) if resource_verified else None
    state = ('unavailable_definition_resource' if not resource_verified
             else 'named_installed_definition' if name is not None
             else 'unmapped_native_code')
    return {'slot_index': slot_index, 'native_code': code,
            'english_definition_name': name, 'name_state': state}


